static const char*ws(const char*p){while(*p==' '||*p=='\t'||*p=='\r'||*p=='\n')p++;return p;}
static int hx(char c){return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:c>='A'&&c<='F'?c-'A'+10:-1;}
