static int jstr(const char**pp,char*out,size_t n){const char*p=ws(*pp);size_t z=0;if(*p++!='"')return-1;while(*p&&*p!='"'){unsigned char x=(unsigned char)*p++;if(x=='\\'){char e=*p++;if(e=='"'||e=='\\'||e=='/')x=(unsigned char)e;else if(e=='b')x='\b';else if(e=='f')x='\f';else if(e=='n')x='\n';else if(e=='r')x='\r';else if(e=='t')x='\t';else if(e=='u'){unsigned u=0;for(int i=0;i<4;i++){int v=hx(*p++);if(v<0)return-1;u=(u<<4)|(unsigned)v;}if(u>=0xd800&&u<=0xdfff)return-1;if(utf8(out,n,&z,u))return-1;continue;}else return-1;}if(x<0x20||z+1>=n)return-1;out[z++]=(char)x;}if(*p++!='"')return-1;out[z]=0;*pp=p;return 0;}
static int skipstr(const char**pp){char tmp[2];const char*p=*pp;if(jstr(&p,tmp,sizeof tmp)==0){*pp=p;return 0;}p=ws(*pp);if(*p++!='"')return-1;while(*p&&*p!='"'){unsigned char x=(unsigned char)*p++;if(x<0x20)return-1;if(x=='\\'){char e=*p++;if(e=='u'){for(int i=0;i<4;i++)if(hx(*p++)<0)return-1;}else if(!strchr("\"\\/bfnrt",e))return-1;}}if(*p++!='"')return-1;*pp=p;return 0;}
