int luca_pbmp_serve(const char*path,const struct luca_pbmp_state*s){int fd=socket(AF_UNIX,SOCK_STREAM,0);if(fd<0)return-1;struct sockaddr_un a={0};a.sun_family=AF_UNIX;if(strlen(path)>=sizeof a.sun_path){close(fd);return-1;}snprintf(a.sun_path,sizeof a.sun_path,"%s",path);unlink(path);if(bind(fd,(struct sockaddr*)&a,sizeof a)||chmod(path,0600)||listen(fd,4)){close(fd);unlink(path);return-1;}for(;;){int c=accept(fd,NULL,NULL);if(c<0)continue;char in[4097],out[16384];size_t used=0;int valid=0;while(used<sizeof in-1){ssize_t z=read(c,in+used,sizeof in-1-used);if(z<=0)break;used+=(size_t)z;char*nl=memchr(in,'\n',used);if(nl){size_t line=(size_t)(nl-in)+1;if(line<=4096){int trailing=0;for(size_t i=line;i<used;i++)if(in[i]!=' '&&in[i]!='\t'&&in[i]!='\r'&&in[i]!='\n'){trailing=1;break;}if(!trailing){in[line]=0;valid=1;}}break;}}if(valid&&!luca_pbmp_response(in,s,out,sizeof out))write(c,out,strlen(out));close(c);}return 0;}
